import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';

test('the native name field preserves Unicode and spaces within forty UTF-16 units', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const name = page.getByRole('textbox', { name: 'Deal name', exact: true });
  await expect(name).toHaveValue('');
  await expect(name).toHaveAttribute('type', 'text');
  await expect(name).toHaveAttribute('maxlength', '40');
  await expect(page.locator('details').getByLabel('Deal name', { exact: true })).toBeVisible();
  const limit = '😀'.repeat(20);
  await name.fill(limit);
  await name.press('End');
  await page.keyboard.type('x');
  await expect(name).toHaveValue(limit);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ version: 2, name: limit });
  await page.locator('summary').click();
  await name.fill('   ');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ version: 2, name: '   ' });
});

test('renaming active progress preserves its deal, draft, cards and running mismatch clock', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(175);
  const before = await exportedSnapshot(page);
  await page.locator('summary').click();
  const board = page.getByLabel('Board code', { exact: true });
  await board.fill('unfinished board draft');
  const name = page.getByLabel('Deal name', { exact: true });
  const title = '  Café 😀  ';
  await name.fill(title);
  await expect(name).toBeFocused();
  await expect(board).toHaveValue('unfinished board draft');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual({ ...before, version: 2, name: title });
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await page.clock.runFor(624);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  await expect(page.locator('.card.matched')).toHaveCount(2);
  const named = await exportedSnapshot(page);
  expect(named).toMatchObject({ name: title, elapsedMs: 800, moves: 2 });
  await page.locator('summary').click();
  await expect(board).toHaveValue('unfinished board draft');
  await name.fill('');
  await page.locator('summary').click();
  const { name: removed, ...progress } = named;
  expect(removed).toBe(title);
  expect(await exportedSnapshot(page)).toEqual({ ...progress, version: 1 });
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';

test('reordered named progress restores its name and remains paused through editing until Resume', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const saved = {
    name: '  Café 😀  ',
    elapsedMs: 1500,
    selection: { remainingMs: 300, second: 2, first: 1, kind: 'mismatch' },
    started: true,
    matched: [0, 11],
    boardCode: EXAMPLE_CODE,
    moves: 2,
    version: 2,
  };
  await page.locator('summary').click();
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(JSON.stringify(saved));
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await load.click();
  await expect(load).toBeFocused();
  const name = page.getByLabel('Deal name', { exact: true });
  await expect(name).toHaveValue(saved.name);
  await expect(page.getByRole('status')).toHaveText('Loaded snapshot. Select Resume to continue.');
  await name.fill('  Paused 😀  ');
  await page.locator('summary').click();
  const renamed = { ...saved, name: '  Paused 😀  ' };
  expect(await exportedSnapshot(page)).toEqual(renamed);
  await page.locator('.card').nth(4).click();
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowRight');
  await expect(page.locator('.card').nth(5)).toBeFocused();
  await page.clock.runFor(2000);
  expect(await exportedSnapshot(page)).toEqual(renamed);
  const resume = page.getByRole('button', { name: 'Resume', exact: true });
  await resume.click();
  await expect(page.locator('.card').nth(5)).toBeFocused();
  await expect(resume).toHaveCount(0);
  await page.clock.runFor(299);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  expect(await exportedSnapshot(page)).toMatchObject({
    name: renamed.name,
    elapsedMs: 1800,
    selection: { kind: 'closed' },
  });
});

test('completed named imports stay static and editable while a resumed named win records its best', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const completed = {
    version: 2,
    name: 'Finished Café',
    boardCode: EXAMPLE_CODE,
    matched: Array.from({ length: 16 }, (_, index) => index),
    selection: { kind: 'closed' },
    moves: 8,
    elapsedMs: 500,
    started: true,
  };
  await page.locator('summary').click();
  const field = page.getByLabel('Snapshot JSON', { exact: true });
  const name = page.getByLabel('Deal name', { exact: true });
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await field.fill(JSON.stringify(completed));
  await load.click();
  await expect(name).toHaveValue(completed.name);
  await expect(page.getByRole('status')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.victory')).not.toHaveClass(/celebrate/);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('none');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await name.fill('Edited completed game');
  await page.clock.runFor(2000);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual({ ...completed, name: 'Edited completed game' });
  await expect(page.locator('.victory')).not.toHaveClass(/celebrate/);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('none');

  await page.locator('summary').click();
  await field.fill(
    JSON.stringify({
      ...completed,
      name: 'One pair left',
      matched: EXAMPLE_PAIRS.slice(0, -1).flat(),
      moves: 7,
    }),
  );
  await load.click();
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  for (const index of EXAMPLE_PAIRS[7]) await page.locator('.card').nth(index).click();
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
  await expect(page.locator('.victory')).toHaveClass(/celebrate/);
  expect(await exportedSnapshot(page)).toMatchObject({ version: 2, name: 'One pair left' });
});
import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';
import { PREFERENCES_KEY } from '../src/game/session/storage.ts';

test('fresh-deal actions and legacy imports clear names while reload stores only preferences', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('summary').click();
  const name = page.getByLabel('Deal name', { exact: true });
  for (const label of ['New Game', 'Restart']) {
    await name.fill('Reset this name');
    await page.getByRole('button', { name: label, exact: true }).click();
    await expect(name).toHaveValue('');
  }
  await name.fill('Resize this name');
  await page.getByLabel('Grid size', { exact: true }).selectOption('6');
  await expect(name).toHaveValue('');
  await name.fill('Load another board');
  await page.getByLabel('Board code', { exact: true }).fill('np1-6-1');
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(name).toHaveValue('');
  await name.fill('Replace with legacy');
  const legacy = {
    version: 1,
    boardCode: 'np1-6-1',
    matched: [],
    selection: { kind: 'one', index: 5 },
    moves: 0,
    elapsedMs: 100,
    started: true,
  };
  const field = page.getByLabel('Snapshot JSON', { exact: true });
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await field.fill(JSON.stringify(legacy));
  await load.click();
  await expect(name).toHaveValue('');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(legacy);
  await page.locator('summary').click();
  await field.fill(JSON.stringify({ ...legacy, version: 2, name: 'Reload unnamed' }));
  await load.click();
  await expect(name).toHaveValue('Reload unnamed');
  const stored = await page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
  const preferences: unknown = JSON.parse(stored ?? 'null');
  expect(preferences).toEqual({ schemaVersion: 1, size: 6, bestMoves: {} });
  await page.reload();
  await expect(page.getByLabel('Grid size', { exact: true })).toHaveValue('6');
  await page.locator('summary').click();
  await expect(name).toHaveValue('');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({
    version: 1,
    matched: [],
    moves: 0,
    elapsedMs: 0,
    started: false,
    selection: { kind: 'closed' },
  });
});

test('invalid board and named snapshot drafts preserve the current name and progress', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('summary').click();
  const name = page.getByLabel('Deal name', { exact: true });
  await name.fill('  Keep Café 😀  ');
  await page.locator('summary').click();
  const before = await exportedSnapshot(page);
  await page.locator('summary').click();
  const board = page.getByLabel('Board code', { exact: true });
  await board.fill('invalid board');
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(board).toHaveValue('invalid board');
  await expect(name).toHaveValue('  Keep Café 😀  ');
  const field = page.getByLabel('Snapshot JSON', { exact: true });
  for (const invalid of [
    { ...before, name: '' },
    { ...before, name: 'invalid\nname' },
    { ...before, name: 'a'.repeat(41) },
    { ...before, version: 1 },
